import{_ as t,o as s,c as o,a4 as d}from"./chunks/framework.CQGI5ZO3.js";const h=JSON.parse('{"title":"xs-json(5)","description":"The --progress=json event stream, field by field, with a published JSON Schema.","frontmatter":{"title":"xs-json(5)","description":"The --progress=json event stream, field by field, with a published JSON Schema.","manual":"xs-json(5)","manualName":"JSON progress events","sectionNumber":"5"},"headers":[],"relativePath":"json-events.md","filePath":"json-events.md"}'),n={name:"json-events.md"};function a(r,e,c,l,i,p){return s(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="xs-json-5" tabindex="-1">xs-json(5) <a class="header-anchor" href="#xs-json-5" aria-label="Permalink to &quot;xs-json(5)&quot;">​</a></h1><div class="manual-deck"><strong>JSON progress events</strong><p>The --progress=json event stream, field by field, with a published JSON Schema.</p></div><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS {#synopsis}&quot;">​</a></h2><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> --progress=json</span><span style="color:#DEDEDE;"> SRC/</span><span style="color:#DEDEDE;"> DEST/</span><span style="color:#DEDEDE;"> 2&gt; </span><span style="color:#DEDEDE;">events.ndjson</span></span></code></pre></div><p><code>--progress=json</code> writes one JSON object per line to stderr: periodic <code>progress</code> totals, a <code>file</code> record for each transferred regular file, and one final <code>complete</code> record. It produces the same stream on terminals and on pipes, with no cursor escapes. Ordinary stdout (<code>-v</code>, <code>-i</code>, <code>--out-format</code>, <code>--stats</code>) is unaffected.</p><p>The stream is described by <a href="progress.schema.json" download>progress.schema.json ↓</a> (JSON Schema 2020-12). <code>npm run check</code> validates the published recording, and fresh local, dry-run, checksum and push streams, against it. Every field is listed, and an unlisted field fails the check.</p><aside class="manual-note"><span>PARSING</span><p>Diagnostics also go to stderr, as plain text. Treat only lines that start with <code>{</code> as events. All counters are raw integers that are never scaled by <code>-h</code>. The schema describes the current output and is not versioned; it is not the versioned machine interface planned for the GUI.</p></aside><h2 id="records" tabindex="-1">RECORDS <a class="header-anchor" href="#records" aria-label="Permalink to &quot;RECORDS {#records}&quot;">​</a></h2><h3 id="record-progress"><code>progress</code> records</h3><p>Periodic totals, emitted on every display tick.</p><div class="manual-table-wrap"><table><thead><tr><th scope="col">Field</th><th scope="col">Type</th><th scope="col">Meaning</th></tr></thead><tbody><tr><td><code>type</code></td><td>string</td><td>Always <code>&quot;progress&quot;</code>.</td></tr><tr><td><code>elapsed_ms</code></td><td>integer</td><td>Milliseconds since the transfer started.</td></tr><tr><td><code>files</code></td><td>integer</td><td>Regular files completed so far.</td></tr><tr><td><code>files_total</code></td><td>integer</td><td>Regular files planned so far. Grows while scanning.</td></tr><tr><td><code>bytes</code></td><td>integer</td><td>Logical file bytes completed. On a push this follows receiver acknowledgments.</td></tr><tr><td><code>bytes_total</code></td><td>integer</td><td>Logical file bytes planned so far.</td></tr><tr><td><code>files_seen</code></td><td>integer</td><td>Source entries discovered by the scan.</td></tr><tr><td><code>wire_bytes</code></td><td>integer</td><td>Bytes sent (push) or received (pull) on the connection, including compression and framing. Zero for local copies.</td></tr><tr><td><code>phase</code></td><td>string</td><td>What the transfer is doing now. One of <code>scanning</code>, <code>transferring</code>, <code>deleting</code>, <code>verifying</code>, <code>waiting for receiver</code>, <code>waiting for sender</code>.</td></tr><tr><td><code>deleted</code></td><td>integer</td><td>Destination entries deleted.</td></tr><tr><td><code>verified</code></td><td>integer</td><td>Successful checksum checks; source and destination hashes each count once.</td></tr><tr><td><code>scanning</code></td><td>boolean</td><td>True while the source scan is still running.</td></tr><tr><td><code>dry_run</code></td><td>boolean</td><td>True for <code>-n</code>; counts describe the plan, and nothing is written.</td></tr></tbody></table></div><h3 id="record-file"><code>file</code> records</h3><p>One transferred regular file (including clones and hard-link members), emitted after the destination operation succeeds, or once per planned file in a dry run.</p><div class="manual-table-wrap"><table><thead><tr><th scope="col">Field</th><th scope="col">Type</th><th scope="col">Meaning</th></tr></thead><tbody><tr><td><code>type</code></td><td>string</td><td>Always <code>&quot;file&quot;</code>.</td></tr><tr><td><code>path</code></td><td>string</td><td>Transfer-relative path. Valid UTF-8 is kept; control bytes are JSON-escaped, and invalid bytes appear as the Unicode code points of their byte values.</td></tr><tr><td><code>path_bytes_hex</code></td><td>string</td><td>The exact path bytes, hex encoded. Use this when names are not UTF-8.</td></tr><tr><td><code>code</code></td><td>string</td><td>The itemize change code, as printed by <code>-i</code>.</td></tr><tr><td><code>size</code></td><td>integer</td><td>File size in bytes.</td></tr><tr><td><code>bytes</code></td><td>integer</td><td>File-content bytes transferred (literal data). Zero for clones and dry runs; only the tail for a resumed file.</td></tr><tr><td><code>dry_run</code></td><td>boolean</td><td>True for <code>-n</code>; counts describe the plan, and nothing is written.</td></tr></tbody></table></div><h3 id="record-complete"><code>complete</code> records</h3><p>Final totals, emitted once at the end. Always the last record.</p><div class="manual-table-wrap"><table><thead><tr><th scope="col">Field</th><th scope="col">Type</th><th scope="col">Meaning</th></tr></thead><tbody><tr><td><code>type</code></td><td>string</td><td>Always <code>&quot;complete&quot;</code>.</td></tr><tr><td><code>elapsed_ms</code></td><td>integer</td><td>Milliseconds since the transfer started.</td></tr><tr><td><code>files</code></td><td>integer</td><td>Regular files completed so far.</td></tr><tr><td><code>files_total</code></td><td>integer</td><td>Regular files planned so far. Grows while scanning.</td></tr><tr><td><code>bytes</code></td><td>integer</td><td>Logical file bytes completed. On a push this follows receiver acknowledgments.</td></tr><tr><td><code>bytes_total</code></td><td>integer</td><td>Logical file bytes planned so far.</td></tr><tr><td><code>files_seen</code></td><td>integer</td><td>Source entries discovered by the scan.</td></tr><tr><td><code>wire_bytes</code></td><td>integer</td><td>Bytes sent (push) or received (pull) on the connection, including compression and framing. Zero for local copies.</td></tr><tr><td><code>phase</code></td><td>string</td><td>Always &quot;complete&quot;. Always <code>&quot;complete&quot;</code>.</td></tr><tr><td><code>deleted</code></td><td>integer</td><td>Destination entries deleted.</td></tr><tr><td><code>verified</code></td><td>integer</td><td>Successful checksum checks; source and destination hashes each count once.</td></tr><tr><td><code>scanning</code></td><td>boolean</td><td>True while the source scan is still running.</td></tr><tr><td><code>dry_run</code></td><td>boolean</td><td>True for <code>-n</code>; counts describe the plan, and nothing is written.</td></tr><tr><td><code>success</code></td><td>boolean</td><td>True only if the transfer finished with exit status 0.</td></tr><tr><td><code>exit_code</code></td><td>integer or null</td><td>The process exit status, or null if cleanup began before a fatal status was known.</td></tr></tbody></table></div><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES {#examples}&quot;">​</a></h2><div class="example-caption">The final JSON record of a transfer</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> --progress=json</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;"> 2&gt;&amp;1 &gt;</span><span style="color:#DEDEDE;">/dev/null</span><span style="color:#DEDEDE;"> | jq </span><span style="color:#DEDEDE;">-c</span><span style="color:#DEDEDE;"> &#39;select(.type == &quot;complete&quot;)&#39;</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>{&quot;type&quot;:&quot;complete&quot;,&quot;elapsed_ms&quot;:3,&quot;files&quot;:5,&quot;files_total&quot;:5,&quot;bytes&quot;:1289005,&quot;bytes_total&quot;:1289005,&quot;files_seen&quot;:5,&quot;wire_bytes&quot;:0,&quot;phase&quot;:&quot;complete&quot;,&quot;deleted&quot;:0,&quot;verified&quot;:0,&quot;scanning&quot;:false,&quot;dry_run&quot;:false,&quot;success&quot;:true,&quot;exit_code&quot;:0}</code></pre></div><div class="example-caption">Transferred files from JSON events</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> --progress=json</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;"> 2&gt;&amp;1 &gt;</span><span style="color:#DEDEDE;">/dev/null</span><span style="color:#DEDEDE;"> | jq </span><span style="color:#DEDEDE;">-r</span><span style="color:#DEDEDE;"> &#39;select(.type == &quot;file&quot;) | [.code, .size, .path] | @tsv&#39;</span><span style="color:#DEDEDE;"> | sort </span><span style="color:#DEDEDE;">-k3</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>&gt;f+++++++++	1288895	archive/2026-q3.log
&gt;f+++++++++	33	docs/guide.md
&gt;f+++++++++	42	docs/images/diagram.svg
&gt;f+++++++++	14	notes.txt
&gt;f+++++++++	21	scripts/build.sh</code></pre></div><div class="example-caption">A Python consumer that ignores diagnostics and reports the outcome</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> --delete</span><span style="color:#DEDEDE;"> --progress=json</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;"> 2&gt; </span><span style="color:#DEDEDE;">events.ndjson</span></span>
<span class="line"><span style="color:#DEDEDE;">python3 </span><span style="color:#DEDEDE;">-</span><span style="color:#DEDEDE;"> events.ndjson</span><span style="color:#DEDEDE;"> &lt;&lt;</span><span style="color:#DEDEDE;">&#39;PY&#39;</span></span>
<span class="line"><span style="color:#DEDEDE;">import json, sys</span></span>
<span class="line"><span style="color:#DEDEDE;">events = [json.loads(line) for line in open(sys.argv[1]) if line.startswith(&#39;{&#39;)]</span></span>
<span class="line"><span style="color:#DEDEDE;">files = [e for e in events if e[&#39;type&#39;] == &#39;file&#39;]</span></span>
<span class="line"><span style="color:#DEDEDE;">done = events[-1]</span></span>
<span class="line"><span style="color:#DEDEDE;">print(f&quot;{len(files)} files, {sum(e[&#39;bytes&#39;] for e in files):,} bytes sent&quot;)</span></span>
<span class="line"><span style="color:#DEDEDE;">print(f&quot;deleted {done[&#39;deleted&#39;]}, exit {done[&#39;exit_code&#39;]}, success {done[&#39;success&#39;]}&quot;)</span></span>
<span class="line"><span style="color:#DEDEDE;">PY</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>5 files, 1,289,005 bytes sent
deleted 1, exit 0, success True</code></pre></div><h2 id="behavior" tabindex="-1">BEHAVIOR <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;BEHAVIOR {#behavior}&quot;">​</a></h2><ul><li><strong>Order.</strong> <code>progress</code> and <code>file</code> records interleave as work happens. Once a transfer starts, <code>complete</code> is its last event, even when it fails (for example, <code>&quot;exit_code&quot;:25</code> when <code>--max-delete</code> stops deletions). A failure during setup, such as a missing source or an invalid option, exits before any event is written, so check the process exit status as well.</li><li><strong>Dry runs.</strong> With <code>-n</code>, <code>file</code> records describe planned operations, and <code>dry_run</code> is true throughout.</li><li><strong>Pushes.</strong> <code>bytes</code> follows what the receiver has acknowledged writing, so it can trail <code>wire_bytes</code>.</li><li><strong>Remote transfers.</strong> JSON events need a helper that supports structured file events. If the helper lacks them, or the transfer would otherwise fall back to rsync, xs exits with an error instead, because rsync cannot produce this stream.</li><li><strong>Suppression.</strong> <code>--no-progress</code> or <code>--quiet</code> suppresses the stream. The last progress-mode option on the command line wins.</li></ul>`,29)])])}const E=t(n,[["render",a]]);export{h as __pageData,E as default};
